style:
body {
    background-color: #f0f2f5;
    font-family: 'Inter', sans-serif;
    margin: 0;
    padding: 0;
}
.dashboard-container {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
    gap: 20px;
    padding: 30px;
    max-width: 1300px;
    margin: 0 auto;
}
.dashboard-btn {
    background: linear-gradient(145deg, #ffffff, #e6e6e6);
    border: none;
    border-radius: 12px;
    padding: 20px;
    font-size: 16px;
    font-weight: 500;
    color: #1a1a1a;
    text-align: center;
    cursor: pointer;
    box-shadow: 5px 5px 15px rgba(0, 0, 0, 0.1), -5px -5px 15px rgba(255, 255, 255, 0.8);
    transition: all 0.3s ease;
    position: relative;
    overflow: hidden;
}
.dashboard-btn:hover {
    transform: translateY(-5px);
    box-shadow: 8px 8px 20px rgba(0, 0, 0, 0.15), -8px -8px 20px rgba(255, 255, 255, 0.9);
    background: linear-gradient(145deg, #f5f5f5, #d9d9d9);
}
.dashboard-btn:active {
    transform: translateY(0);
    box-shadow: 3px 3px 10px rgba(0, 0, 0, 0.1), -3px -3px 10px rgba(255, 255, 255, 0.7);
}
.dashboard-btn::before {
    content: '';
    position: absolute;
    top: 0;
    left: -100%;
    width: 100%;
    height: 100%;
    background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.3), transparent);
    transition: 0.5s;
}
.dashboard-btn:hover::before {
    left: 100%;
}
@media (max-width: 600px) {
    .dashboard-btn {
        font-size: 14px;
        padding: 15px;
    }
}

/* Reset */
html {
  box-sizing: border-box;
}
*, *:before, *:after {
  box-sizing: inherit;
}

/* Body styling */
body {
  display: flex;
  min-height: auto;
  background: whitesmoke;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif, "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol";
  font-size: 16px;
  font-weight: 700;
  justify-content: center;
  align-items: center;
  margin: 0;
}

/* Container styles */
.container {
  display: flex;
  flex-direction: column;
  width: 100%;
  padding: 20px;
}

/* Button container layout */
.button-container {
  display: flex;
  flex-wrap: wrap;
  gap: 20px;
  justify-content: center;
  margin-top: -30px;
}

/* Button styles */
.button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 12px 20px;
  font-size: 14px;
  font-weight: bold;
  color: #fff;
  text-align: center;
  text-decoration: none;
  border: none;
  border-radius: 10px;
  cursor: pointer;
  transition: all 0.3s ease;
  box-shadow: 0px 4px 8px rgba(0, 0, 0, 0.15);
  flex: 1 0 calc(33.33% - 20px); /* Approximately 1/3 of the container width minus gap */
  /*max-width: 200px; */
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.button-icon {
  width: 20px;
  height: 20px;
  margin-right: 8px;
  vertical-align: middle;
}

/* Button specific colors */
.button.-dark {
  background: linear-gradient(135deg, #161616, #777777); /* Dark gradient for Sales Invoice */
}

.button.-dark-alt {
  background: linear-gradient(135deg, #2a2a2a, #555555); /* Slightly lighter dark gradient for Purchase Invoice */
}

.button.-transparent {
  background: transparent;
  border: 2px solid #555555; /* Darker border to match new theme */
  color: #555555; /* Match border color for text */
  box-shadow: none;
}

/* Button hover effects */
.button:hover {
  opacity: 0.85;
  transform: translateY(-2px);
  color: #fff;
  text-decoration: none;
}

.button:active {
  opacity: 0.75;
  transform: translateY(0);
}

.button.-dark:hover {
  background: linear-gradient(135deg, #777, #161616); /* Darker gradient on hover */
}

.button.-dark-alt:hover {
  background: linear-gradient(135deg, #555, #2a2a2a); /* Darker gradient on hover for purchase */
}

.button.-transparent:hover {
  background: rgba(85, 85, 85, 0.1); /* Slight background on hover */
  color: #555555;
  border-color: #2a2a2a; /* Darker border on hover */
}

/* Responsive adjustments */
@media (max-width: 768px) {
  .button {
    flex: 1 0 calc(50% - 10px); /* Two buttons per row on medium screens */
    max-width: 150px;
  }
}

@media (max-width: 480px) {
  .button {
    flex: 1 0 100%; /* One button per row on small screens */
    max-width: 100%;
  }
  .button-container {
    gap: 10px;
  }
}

